            case "MINUTES" -> Optional.of(Duration.ofMinutes(amount));
            case "HOURS" -> Optional.of(Duration.ofHours(amount));
            case "DAYS" -> Optional.of(Duration.ofDays(amount));
            default -> Optional.empty();
